def remove_duplicates(items):
    """Return a new list with duplicates removed, preserving first-occurrence order.

    Works for hashable elements. Raises TypeError if an element is unhashable.
    """
    seen = set()
    result = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError as exc:
            raise TypeError(
                f"remove_duplicates requires hashable elements; got unhashable "
                f"element of type {type(item).__name__!r}"
            ) from exc
        result.append(item)
    return result
```

