def list_intersection(a: list, b: list) -> list:
    """Return unique elements present in both lists, preserving order of `a`.

    Elements must be hashable. Raises TypeError if an element is unhashable.
    """
    try:
        b_set = set(b)
    except TypeError as exc:
        raise TypeError(
            "list_intersection requires hashable elements in the second list"
        ) from exc

    seen = set()
    result = []
    for item in a:
        try:
            if item in b_set and item not in seen:
                seen.add(item)
                result.append(item)
        except TypeError as exc:
            raise TypeError(
                f"list_intersection requires hashable elements; got {type(item).__name__}"
            ) from exc
    return result
