from typing import Iterable, List, TypeVar

T = TypeVar("T")


def intersection_no_duplicates(a: Iterable[T], b: Iterable[T]) -> List[T]:
    """Return unique elements present in both ``a`` and ``b``.

    Order follows first appearance in ``a``. Elements must be hashable.
    """
    try:
        b_set = set(b)
    except TypeError as exc:
        raise TypeError(
            "Elements of the second list must be hashable to compute an intersection."
        ) from exc

    seen = set()
    result: List[T] = []
    for item in a:
        try:
            if item in b_set and item not in seen:
                seen.add(item)
                result.append(item)
        except TypeError as exc:
            raise TypeError(
                f"Element {item!r} is unhashable; intersection requires hashable elements."
            ) from exc
    return result
