def transpose(matrix: list[list]) -> list[list]:
    """Return the transpose of a rectangular matrix given as a list of lists.

    Raises:
        TypeError: If ``matrix`` is not a list of lists.
        ValueError: If ``matrix`` is empty or its rows have unequal lengths.
    """
    if not isinstance(matrix, list):
        raise TypeError(f"matrix must be a list, got {type(matrix).__name__}")
    if not matrix:
        raise ValueError("matrix must not be empty")

    for i, row in enumerate(matrix):
        if not isinstance(row, list):
            raise TypeError(f"row {i} must be a list, got {type(row).__name__}")

    n_cols = len(matrix[0])
    for i, row in enumerate(matrix):
        if len(row) != n_cols:
            raise ValueError(
                f"matrix must be rectangular: row 0 has {n_cols} columns "
                f"but row {i} has {len(row)}"
            )

    # Result has n_cols rows and len(matrix) columns.
    # result[j][i] = matrix[i][j] for j in range(n_cols), i in range(len(matrix)).
    return [[matrix[i][j] for i in range(len(matrix))] for j in range(n_cols)]
