from typing import List, TypeVar, Hashable

T = TypeVar("T", bound=Hashable)


def intersection(a: List[T], b: List[T]) -> List[T]:
    """Return unique elements present in both lists, preserving order of `a`."""
    if not isinstance(a, list) or not isinstance(b, list):
        raise TypeError("Both arguments must be lists")

    try:
        b_set = set(b)
    except TypeError as exc:
        raise TypeError("List elements must be hashable") from exc

    seen = set()
    result = []
    for item in a:
        if item in b_set and item not in seen:
            seen.add(item)
            result.append(item)
    return result
```

