from typing import Union

def decimal_to_binary(decimal_number: Union[int, str]) -> str:
    if isinstance(decimal_number, str):
        if not decimal_number.strip().lstrip("-").isdigit():
            raise ValueError(f"Invalid input: {decimal_number!r}")
        decimal_number = int(decimal_number)
    if not isinstance(decimal_number, int):
        raise ValueError(f"Invalid input: {decimal_number!r}")
    if decimal_number == 0:
        return "0"
    is_negative = decimal_number < 0
    remaining = abs(decimal_number)
    digits = []
    while remaining > 0:
        digits.append(str(remaining % 2))
        remaining //= 2
    binary_text = "".join(reversed(digits))
    return f"-{binary_text}" if is_negative else binary_text
