        TypeError: If ``numbers`` is not iterable or contains non-numeric values.
    """
    try:
        iterator = iter(numbers)
    except TypeError as exc:
        raise TypeError(f"Expected an iterable of numbers, got {type(numbers).__name__}") from exc

    largest: Optional[float] = None
    second: Optional[float] = None

    for value in iterator:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"All elements must be numbers; got {type(value).__name__}: {value!r}")

        if largest is None or value > largest:
            second = largest
            largest = value
        elif value != largest and (second is None or value > second):
            second = value

    return second
