from typing import List


def longest_common_prefix(strs: List[str]) -> str:
    """
    Return the longest common prefix of a list of strings.

    Raises:
        TypeError: If `strs` is not a list or contains non-string elements.
    """
    if not isinstance(strs, list):
        raise TypeError(f"Expected a list of strings, got {type(strs).__name__}")
    for i, s in enumerate(strs):
        if not isinstance(s, str):
            raise TypeError(
                f"Element at index {i} is {type(s).__name__}, expected str"
            )

    if not strs:
        return ""

    # Start with the first string as the candidate prefix.
    prefix = strs[0]
    for s in strs[1:]:
        # Shrink the prefix until it matches the start of `s`.
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix
```

