def two_sum(nums, target):
    """
    Return a tuple of indices (i, j) such that nums[i] + nums[j] == target,
    or None if no such pair exists.

    Uses a single-pass hash map: O(n) time, O(n) space.
    """
    if nums is None:
        raise TypeError("nums must be an iterable of numbers, got None")
    if not isinstance(target, (int, float)):
        raise TypeError(f"target must be a number, got {type(target).__name__}")

    seen = {}
    for i, value in enumerate(nums):
        if not isinstance(value, (int, float)):
            raise TypeError(
                f"nums[{i}] must be a number, got {type(value).__name__}"
            )
        complement = target - value
        if complement in seen:
            return (seen[complement], i)
        seen[value] = i
    return None
```

Example:

```python
print(two_sum([2, 7, 11, 15], 9))   # (0, 1)
print(two_sum([3, 2, 4], 6))        # (1, 2)
print(two_sum([1, 2, 3], 100))      # None
```

