from pathlib import Path

def roman_to_int(roman: str) -> int:
    if not isinstance(roman, str) or not roman:
        raise ValueError("input must be a non-empty string")
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    if any(char not in values for char in roman):
        raise ValueError(f"invalid Roman numeral: {roman}")
    total = 0
    for index, char in enumerate(roman):
        current = values[char]
        next_value = values[roman[index + 1]] if index + 1 < len(roman) else 0
        total += -current if current < next_value else current
    return total
