```python
import os
from typing import List


def get_subdirectory_names(directory: str) -> List[str]:
    """
    Return the names (not full paths) of all immediate subdirectories of `directory`.

    Raises:
        FileNotFoundError: if `directory` does not exist.
        NotADirectoryError: if `directory` is not a directory.
        PermissionError: if the directory cannot be read.
        OSError: for other OS-level failures.
    """
    try:
        with os.scandir(directory) as entries:
            return [entry.name for entry in entries if entry.is_dir()]
    except FileNotFoundError as exc:
        raise FileNotFoundError(
            f"Directory not found: {directory!r}"
        ) from exc
    except NotADirectoryError as exc:
        raise NotADirectoryError(
            f"Path is not a directory: {directory!r}"
        ) from exc
    except PermissionError as exc:
        raise PermissionError(
            f"Permission denied reading directory: {directory!r}"
        ) from exc
    except OSError as exc:
        raise OSError(
            f"Failed to list subdirectories of {directory!r}: {exc}"
        ) from exc
```

`os.scandir` is used as a context manager so the underlying directory handle is always closed, even if an error occurs mid-iteration. `entry.is_dir()` follows symlinks by default; pass `follow_symlinks=False` to `is_dir()` if you want to exclude symlinked directories.

