def write_lines(path: str, lines: list[str], encoding: str = "utf-8") -> None:
    """Write each string in ``lines`` to ``path``, one per line.

    A trailing newline is written after every line, including the last.

    Raises:
        TypeError: if ``lines`` is not a list of strings.
        OSError: if the file cannot be opened or written (e.g. permission
            denied, missing directory, disk full).
    """
    if not isinstance(lines, list):
        raise TypeError(f"lines must be a list, got {type(lines).__name__}")
    for index, line in enumerate(lines):
        if not isinstance(line, str):
            raise TypeError(
                f"lines[{index}] must be str, got {type(line).__name__}"
            )
        if "\n" in line or "\r" in line:
            raise ValueError(
                f"lines[{index}] contains a newline character; "
                "each element must be a single line"
            )

    try:
        with open(path, "w", encoding=encoding, newline="\n") as handle:
            for line in lines:
                handle.write(line)
                handle.write("\n")
    except OSError as exc:
        raise OSError(f"failed to write lines to {path!r}: {exc}") from exc
```

The `with` block guarantees the file handle is closed even if a write fails mid-loop.

