def total_size(directory):
    """Return the total size in bytes of files directly in a directory."""
    total = 0
    with os.scandir(directory) as entries:
        for entry in entries:
            if entry.is_file():
                try:
                    total += entry.stat().st_size
                except OSError:
                    pass
