import os
from pathlib import Path


def list_txt_files(directory: str) -> list[str]:
    """Return the names of all .txt files directly inside `directory`.

    Raises:
        FileNotFoundError: if `directory` does not exist.
        NotADirectoryError: if `directory` is not a directory.
        PermissionError: if the directory cannot be read.
    """
    dir_path = Path(directory)

    if not dir_path.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory!r}")
    if not dir_path.is_dir():
        raise NotADirectoryError(f"Path is not a directory: {directory!r}")

    try:
        with os.scandir(dir_path) as entries:
            return sorted(
                entry.name
                for entry in entries
                if entry.is_file() and entry.name.lower().endswith(".txt")
            )
    except PermissionError as exc:
        raise PermissionError(
            f"Permission denied while reading directory: {directory!r}"
        ) from exc
    except OSError as exc:
        raise OSError(
            f"Failed to list directory {directory!r}: {exc}"
        ) from exc
```

`os.scandir` is used as a context manager so the directory handle is always closed, even if iteration raises. Matching is case-insensitive (`.TXT` included); drop `.lower()` if you want exact `.txt` only.

