```python
import shutil


def copy_text_file(source_path: str, destination_path: str) -> None:
    """Copy the text content of ``source_path`` to ``destination_path``.

    The source is read as UTF-8 text and written as UTF-8 text. File handles
    are managed with context managers so they are always closed, even on error.

    Raises:
        FileNotFoundError: if ``source_path`` does not exist.
        IsADirectoryError: if either path refers to a directory.
        PermissionError: if the process lacks read/write permission.
        UnicodeDecodeError: if the source is not valid UTF-8 text.
        OSError: for other I/O failures (e.g. disk full, invalid path).
    """
    try:
        with open(source_path, "r", encoding="utf-8") as src:
            content = src.read()
    except FileNotFoundError as exc:
        raise FileNotFoundError(
            f"Source file not found: {source_path!r}"
        ) from exc
    except IsADirectoryError as exc:
        raise IsADirectoryError(
            f"Source path is a directory, not a file: {source_path!r}"
        ) from exc
    except PermissionError as exc:
        raise PermissionError(
            f"Permission denied reading source file: {source_path!r}"
        ) from exc
    except UnicodeDecodeError as exc:
        raise UnicodeDecodeError(
            exc.encoding, exc.object, exc.start, exc.end,
            f"Source file is not valid UTF-8 text: {source_path!r}"
        ) from exc
    except OSError as exc:
        raise OSError(
            f"Failed to read source file {source_path!r}: {exc}"
        ) from exc

    try:
        with open(destination_path, "w", encoding="utf-8") as dst:
            dst.write(content)
    except IsADirectoryError as exc:
        raise IsADirectoryError(
            f"Destination path is a directory, not a file: {destination_path!r}"
        ) from exc
    except PermissionError as exc:
        raise PermissionError(
            f"Permission denied writing destination file: {destination_path!r}"
        ) from exc
    except OSError as exc:
        raise OSError(
            f"Failed to write destination file {destination_path!r}: {exc}"
        ) from exc
```

If you only need a byte-for-byte copy (preserving encoding and metadata), `shutil.copy2(source_path, destination_path)` is the standard-library alternative; it raises `FileNotFoundError`, `IsADirectoryError`, `PermissionError`, and `OSError` on failure.

