from pathlib import Path


def build_log_line(timestamp: str, level: str, message: str) -> str:
    if not timestamp or not level or not message:
        raise ValueError("timestamp, level and message must be non-empty")
    if not Path(timestamp).name:
        raise ValueError("timestamp must be a valid string")
    normalized_level = level.strip().upper()
    if normalized_level not in {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}:
        raise ValueError(f"invalid level: {level}")
    return f"{timestamp} [{normalized_level}] {message}"


def build_log_line_now(level: str, message: str) -> str:
    timestamp = datetime.now().isoformat(timespec="seconds")
    return build_log_line(timestamp, level, message)
