def render_point(point):
    """Render a 2D point as '(x, y)'.

    Args:
        point: A sequence of exactly two numbers (e.g. tuple, list).

    Returns:
        A string of the form '(x, y)'.

    Raises:
        TypeError: If point is not a sequence of two numbers.
        ValueError: If point does not contain exactly two elements.
    """
    try:
        x, y = point
    except TypeError as exc:
        raise TypeError(
            f"point must be an iterable of two numbers, got {type(point).__name__}"
        ) from exc
    except ValueError as exc:
        raise ValueError(
            f"point must contain exactly two elements, got {len(point)}"
        ) from exc

    for name, value in (("x", x), ("y", y)):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(
                f"{name} coordinate must be a number, got {type(value).__name__}"
            )

    return f"({x}, {y})"
```

