def compute_bmi(weight_kg: float, height_m: float) -> float:
    """Compute BMI = weight_kg / height_m**2.

    Raises:
        TypeError: If either argument is not a real number.
        ValueError: If weight_kg or height_m is not strictly positive.
    """
    for name, value in (("weight_kg", weight_kg), ("height_m", height_m)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a real number, got {type(value).__name__}")
        if value != value:  # NaN check
            raise ValueError(f"{name} must be a finite number, got NaN")
        if value <= 0:
            raise ValueError(f"{name} must be positive, got {value}")

    return weight_kg / (height_m ** 2)
```

