def nth_element(sequence, n):
    """
    Return the n-th element of `sequence` using 0-based indexing.

    Raises:
        TypeError: If `n` is not an integer (bool is rejected as well).
        ValueError: If `n` is negative.
        IndexError: If `n` is out of range for the sequence.
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(f"n must be an int, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"n must be non-negative, got {n}")

    try:
        return sequence[n]
    except IndexError as exc:
        raise IndexError(
            f"n={n} is out of range for sequence of length {len(sequence)}"
        ) from exc
