def nth_prime(n: int) -> int:
    """Return the n-th prime (1-indexed). Raises ValueError if n < 1."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError(f"n must be an int, got {type(n).__name__}")
    if n < 1:
        raise ValueError(f"n must be >= 1, got {n}")

    # Upper bound for the n-th prime (n >= 6): p_n < n * (ln n + ln ln n).
    # For small n we use a fixed safe bound.
    import math
    if n < 6:
        limit = 15
    else:
        limit = int(n * (math.log(n) + math.log(math.log(n)))) + 10

    # Sieve of Eratosthenes over [0, limit]
    sieve = bytearray([1]) * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i : limit + 1 : i] = b"\x00" * (((limit - i * i) // i) + 1)

    count = 0
    for value in range(2, limit + 1):
        if sieve[value]:
            count += 1
            if count == n:
                return value

    raise RuntimeError(f"sieve limit {limit} too small for n={n}")
```

