from pathlib import Path

def is_balanced(text: str) -> bool:
    pairs = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []
    for char in text:
        if char in "([{":
            stack.append(char)
            continue
        if char not in pairs:
            continue
        if not stack or stack.pop() != pairs[char]:
            return False
    return not stack

def check_balanced(text: str) -> bool:
    if not isinstance(text, str):
        raise ValueError(f"Expected str, got {type(text).__name__}")
    return is_balanced(text)

def check_balanced_file(path: str) -> bool:
    file_path = Path(path)
    if not file_path.is_file():
        raise ValueError(f"Not a file: {path}")
    return is_balanced(file_path.read_text())
