def dot_product(a: list[float], b: list[float]) -> float:
    """Compute the dot product of two equal-length vectors.

    Raises:
        TypeError: If either argument is not a list/tuple of numbers.
        ValueError: If the vectors have different lengths.
    """
    if not isinstance(a, (list, tuple)) or not isinstance(b, (list, tuple)):
        raise TypeError(
            f"Both arguments must be list or tuple, got {type(a).__name__} and {type(b).__name__}"
        )
    if len(a) != len(b):
        raise ValueError(
            f"Vector length mismatch: {len(a)} != {len(b)}"
        )
    total = 0.0
    for i, (x, y) in enumerate(zip(a, b)):
        if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
            raise TypeError(
                f"Non-numeric element at index {i}: {x!r}, {y!r}"
            )
        total += x * y
    return total
```

