from pathlib import Path
from typing import List

def merge_sorted_lists(first_list: List[int], second_list: List[int]) -> List[int]:
    if not isinstance(first_list, list) or not isinstance(second_list, list):
        raise ValueError("Both inputs must be lists")
    if first_list != sorted(first_list) or second_list != sorted(second_list):
        raise ValueError("Both input lists must be sorted")
    merged_list: List[int] = []
    first_index: int = 0
    second_index: int = 0
    while first_index < len(first_list) and second_index < len(second_list):
        if first_list[first_index] <= second_list[second_index]:
            merged_list.append(first_list[first_index])
            first_index += 1
            continue
        merged_list.append(second_list[second_index])
        second_index += 1
    return merged_list + first_list[first_index:] + second_list[second_index:]

def merge_sorted_lists_from_files(first_path: Path, second_path: Path) -> List[int]:
    if not first_path.is_file() or not second_path.is_file():
        raise ValueError(f"Both paths must be existing files: {first_path}, {second_path}")
    first_list: List[int] = [int(line) for line in first_path.read_text().splitlines() if line.strip()]
    second_list: List[int] = [int(line) for line in second_path.read_text().splitlines() if line.strip()]
    return merge_sorted_lists(first_list, second_list)
